{"content":""""Remove duplicate records, keeping the first occurrence.

Two strategies, chosen by probing the input:

1. Hashable keys (including tuples/lists/sets/dicts whose contents are all
   hashable, as produced by e.g. ``key=lambda r: (r.get("source"), ...)``):
   plain ``set`` membership -- O(1) per record.

2. Unhashable keys (the default for records containing nested dicts or
   lists): keys are canonicalized into a hashable form that preserves
   equality (``k1 == k2`` iff ``canon(k1) == canon(k2)``), so membership
   still costs O(1) in average time.
"""


def _canonical(value):
    """Return a hashable form of ``value`` that preserves equality.

    - dicts become a tagged, sorted tuple of canonicalized (key, value)
      pairs, so ``{"a": 1, "b": 2} == {"b": 2, "a": 1}`` still compares
      equal after canonicalization.
    - lists keep their order; tuples, sets and frozensets are handled too.
    - Everything else (scalars, bytes, user objects with ``__eq__``/``__hash__``)
      is tagged with its type.
    """
    if isinstance(value, dict):
        return (
            "dict",
            tuple(sorted(
                ((_canonical(k), _canonical(v)))
                for k, v in value.items()
            ), key=repr)),
    if isinstance(value, list):
        return ("list", tuple(_canonical(x) for x in value))
    if isinstance(value, tuple):
        return ("tuple", tuple(_canonical(x) for x in value))
    if isinstance(value, (set, frozenset)):
        return ("set", tuple(sorted((_canonical(x),) for x in value), key=repr))
    # Scalars / user objects.
    try:
        hash(value)
    except TypeError:
        # Unhashable non-container (or a dict/list/etc. with unhashable
        # internals that slipped through, e.g. a dict with a list key).
        # Caller falls back to a linear scan.
        raise
    return (type(value), value)


def dedupe(records, key=None):
    # Probe the first record: if its key hashes, use a plain set for the
    # whole input (hashability of the rest is still guarded per-key below,
    # but this covers the overwhelming common case).
    it = iter(records)
    first = None
    try:
        first = next(it)
    except StopIteration:
        return []

    def _k(r):
        return key(r) if key else r

    try:
        k0 = _k(first)
        hash(k0)
    except TypeError:
        k0 = None

    out = [first]
    if k0 is not None:
        # Fast path 1: hashable keys.
        seen = {k0}
        for r in it:
            try:
                k = _k(r)
                if k not in seen:
                    seen.add(k)
                    out.append(r)
            except TypeError:
                # A later key turned out to be unhashable; rebuild the
                # canonical set from what we have and continue with
                # fast path 2.
                return _canonical_path(out, it, key)
        return out

    # Fast path 2: canonicalize unhashable keys.
    return _canonical_path(out, it, key)


def _canonical_path(out, rest, key):
    seen = set()
    for r in out:
        seen.add(_canonical(key(r) if key else r))
    for r in rest:
        k = key(r) if key else r
        try:
            c = _canonical(k)
        except TypeError:
            # Cannot canonicalize at all (e.g. dict with list keys):
            # fall back to exact linear-scan equality, which is what the
            # original implementation did.
            return _linear_tail(out, seen, rest, key)
        if c not in seen:
            seen.add(c)
            out.append(r)
    return out


def _linear_tail(out, seen, rest, key):
    # Some keys cannot be hashed or canonicalized. For those we must
    # compare by direct equality against every previously kept key.
    linear_keys = [key(r) if key else r for r in out]
    for r in rest:
        k = key(r) if key else r
        if k not in linear_keys:
            linear_keys.append(k)
            out.append(r)
    return out
